# Additional RA10 practice set tasks for Unit 2 (marketing campaign). Template + 8 original cases.
import random
from ra10_sets import p, h, stat, grid, act, paper, u2_acts


def dist(n, weights, seed):
    """Integer counts that sum exactly to n, roughly following the weights (with small seeded noise)."""
    r = random.Random(seed)
    w = [x * r.uniform(0.92, 1.08) for x in weights]
    t = sum(w)
    c = [int(n * x / t) for x in w]
    c[w.index(max(w))] += n - sum(c)
    return c


def multi(n, pcts, seed):
    r = random.Random(seed)
    return [max(1, min(n, round(n * x * r.uniform(0.96, 1.04)))) for x in pcts]


def build(c):
    n = c['n']
    sd = c['seed']
    name = c['name']
    A = [h('Set Task Brief'),
         p('You have been asked to write a proposal for a marketing campaign for a business called %s. %s %s' % (name, c['what'], c['aim'])),
         p('You are required to use the research you have been given to independently analyse the market for %s in the UK. This research includes primary and secondary data relating to: competitors; market size, share and structure; target market; trends; external influences; and media options. You are allowed a maximum of two sides of A4 of your individually prepared notes and you may annotate Part A to support you during the Part B supervised assessment.' % c['market']),
         h('The UK %s market' % c['market']), p(c['m1']), p(c['m2']),
         h('Competitors'), grid(['Business', 'Position in the market', 'Typical price', 'Main promotion'], c['comp']), p(c['compnote']),
         h(name), p(c['biz']),
         h('%s: Market Research Report' % name),
         p('Month: %s · Sample size: %d · Location: %s · Sample: %s' % (c['month'], n, c['loc'], c['sample'])),
         stat('Age', c['age_c'], dist(n, c['age_w'], sd + 1))]
    for i, (q, cells, pct, kind) in enumerate(c['stats']):
        if kind == 'one':
            A.append(stat(q, cells, dist(n, pct, sd + 10 + i)))
        else:
            A.append(stat(q + ' (Select all that apply.)', cells, multi(n, pct, sd + 10 + i)))
    A += [h('Research on media selection'), p('%s has researched the following media options for its campaign.' % name), grid(['Media option', 'Costs and information'], c['media'])]
    B = [h(c['bh']), p(c['b1']), h(c['bh2']), p(c['b2']), p('The owners of %s are considering two options to help them achieve their goal:' % name),
         p('EITHER'), p(c['optA']), p('OR'), p(c['optB']), p('The owners of %s have allocated a budget of %s for the campaign. The campaign should run for %s.' % (name, c['budget'], c['dur']))]
    return paper('U2-R%d' % c['k'], 2, '99%02d' % c['k'], '%s — %s' % (name, c['short']), c['theme'], 70, u2_acts(name), A, B)


